// 确定频率用
/*
    @param    data 采样的电压值
    @mask     sin/cos
    1、DC偏置有误差影响不大，mask为周期函数，平均值为0
*/
double corr1000_200(short *data, short *mask)
{
    double res = 0;
    short i;
    //累加
    for (i = 0; i < 1000; i++)
        res = res + (data[i] - 2048) * (mask[i % 200] - 2048); //注意SIN与COS模版要减去直流偏置，才是真正的信号

    return res;
}

// 计算IQ分量的模的长度，频点的功率
double modulus(double I, double Q)
{
    double temp_double;
    temp_double = sqrt(I * I + Q * Q);
    return temp_double;
}

// 计算参与叠加的两个正弦信号的频率
void Cal_Freq(unsigned char *frq) 
{
    //频率计算参数
    double mag_d[19];         // 用于存放输入信号与所有19种信号相关计算的模
    double temp_double[19];
    double corr_sin_double; // 用于存放C与所有19种正弦相关计算的结果
    double corr_cos_double; // 用于存放C与所有19种余弦相关计算的结果
    double sort_temp;
    unsigned char i, j, temp_char;
    for (i = 0; i < 19; i++)
    {
        corr_sin_double = corr1000_200(adc_complex_value, DAC_SIN + 200 * i);
        corr_cos_double = corr1000_200(adc_complex_value, DAC_COS + 200 * i);
        
        mag_d[i] = modulus(corr_sin_double, corr_cos_double);
        temp_double[i] = mag_d[i];
    }

    // 冒泡法对大小进行排序
    for (i = 0; i < 19 - 1; i++)
    {
        for (j = 0; j < 19 - i - 1; j++)
        {
            if (temp_double[j] < temp_double[j + 1])
            {
                sort_temp = temp_double[j];
                temp_double[j] = temp_double[j + 1];
                temp_double[j + 1] = sort_temp;
            }
        }
    }
    // 寻找最大值序号
    for (i = 0; i < 19; i++)
    {
        if (mag_d[i] == temp_double[0]) // 找到最大数
            frq[0] = i;
        if (mag_d[i] == temp_double[1]) // 找到第二大数
            frq[1] = i;
    }
    if (frq[0] > frq[1])
    { // 把频率低的放在第一个位置，如果颠倒就换一下
        temp_char = frq[0];
        frq[0] = frq[1];
        frq[1] = temp_char;
    }
}

// 计算相位偏移
void Get_Pos_Angle(uint8_t flag)
{
		double  temp_double_sin =0;
		double  temp_double_cos =0;
		double temp_double_angle_0 =0;
		double temp_double_angle_1 = 0;
	
		if(flag == 0)
		{
			temp_double_sin = corr1000_200(adc_complex_value, DAC_SIN + 200 * fre[0]);
			temp_double_cos = corr1000_200(adc_complex_value, DAC_COS + 200 * fre[0]);

			temp_double_angle_0 = atan2(temp_double_cos, temp_double_sin);

			if (temp_double_angle_0 < 0) //atan2函数计算得到的相位差在-pi到pi，但当其小于0时，DAC输出的信号无法提前相位，只能将所有相位全部延迟一个周期，即进行一个周期的求补操作
					pos_angle_0 = -temp_double_angle_0;
			else
					pos_angle_0 = 2 * 3.1415926 - temp_double_angle_0;
		}
		 
		else if(flag == 1)
		{
			temp_double_sin = corr1000_200(adc_complex_value, DAC_SIN + 200 * fre[1]);
			temp_double_cos = corr1000_200(adc_complex_value, DAC_COS + 200 * fre[1]);
			temp_double_angle_1 = atan2(temp_double_cos, temp_double_sin);

			if (temp_double_angle_1 < 0) // atan2函数计算得到的相位差在-pi到pi，但当其小于0时，DAC输出的信号无法提前相位，只能将所有相位全部延迟一个周期，即进行一个周期的求补操作
					pos_angle_1 = -temp_double_angle_1;
			else
					pos_angle_1 = 2 * 3.1415926 - temp_double_angle_1;
		}
    
}

// 提高部分
void FFT_Detect_Type(unsigned char *frq, unsigned char *wave_type) // 根据输入信号及已经判断出来的频率值，通过FFT结果判断信号类型是三角波（1）还是正弦波（0）
// 第一个参数指针指向的数组，其中存放的是之前的其他函数计算出来的两个信号的频率
// 第二个参数指正指向的数组用于存放这两个信号的波形种类，0为正弦，其他值为三角波。需要在本函数中计算产生
{
    short indata[2048], outdata[2048], i;
//    int mag[512],sum = 0, average;
    _Bool conti;

    threshold[0] = (frq[0] < 4) ? 50 : 150;//根据实际频谱计算，低于25KHz受噪声影响较大
		threshold[1] = (frq[1] < 4) ? 50 : 150;


    for (i = 0; i < 1024; i++) // 计算信号平均值
        sum = sum + adc_complex_value[i];
    average = sum / 1024;     //  约等于2048

    for (i = 0; i < 1024; i++)
    {
        indata[2 * i] = adc_complex_value[i] - average; // 减去平均值是为了降低直流分量
        indata[2 * i + 1] = 0;
    }

    cr4_fft_1024_stm32(outdata, indata, 1024); //时域转频域

    for (i = 0; i < 512; i++)                                                               // FFT结果幅度谱是左右对称的，只需要算一半
        mag[i] = outdata[2 * i] * outdata[2 * i] + outdata[2 * i + 1] * outdata[2 * i + 1]; // sqrt(outdata[2*i] * outdata[2*i] + outdata[2*i + 1] * outdata[2*i + 1]);

    //////////计算输入信号频率及其三次谐波频率对应在FFT结果数组中的索引值//////////
    //////初步判断第一个信号的类型//////////////
    temp_float = (float)frq[0] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
    
    temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
    temp_float = temp_float * 512;       // 计算输入信号频率对应的数组索引
    index = temp_float + 0.5f;            // 进行四舍五入取整

    temp_float = (float)frq[0] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
    temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
    temp_float = temp_float * 3 * 512;   // 计算三倍基频对应的数组索引
    harmo3_index = temp_float + 0.5f;     // 进行四舍五入取整

    // 计算一次和三次谐波上的能量及其比值
    mag_1harmo[0] = mag[index - 1] + mag[index] + mag[index + 1];
    mag_3harmo[0] = mag[harmo3_index - 1] + mag[harmo3_index] + mag[harmo3_index + 1];
    k[0] = mag_1harmo[0] / mag_3harmo[0];

    wave_type[0] = (k[0] > threshold[0]) ? 0 : 1;//    1 --- 三角波(小于阈值)，0 --- 正弦波(大于阈值)

    // //////////初步判断第二个信号的类型////////////////
    temp_float = (float)frq[1] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
    temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
    temp_float = temp_float * 512;       // 计算输入信号频率对应的数组索引
    index = temp_float + 0.5f;            // 进行四舍五入取整

    temp_float = (float)frq[1] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
    temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
    temp_float = temp_float * 3 * 512;   // 计算三倍基频对应的数组索引
    harmo3_index = temp_float + 0.5f;     // 进行四舍五入取整

    mag_1harmo[1] = mag[index - 1] + mag[index] + mag[index + 1];
    mag_3harmo[1] = mag[harmo3_index - 1] + mag[harmo3_index] + mag[harmo3_index + 1];
    k[1] = mag_1harmo[1] / mag_3harmo[1];

    wave_type[1] = (k[1] > threshold[1]) ? 0 : 1;

    ////////对第二个信号刚好等于第一个信号三倍频率特殊情况，需要重新判断第一个信号的类型/////
    // 上面的初步判断算有问题的是：第二个信号四第一个信号三倍频率的情况，只有可能包括：
    // 1、第一个信号是10K，第二个信号是30K
    // 2、第一个信号是15K，第二个信号是45K
    // 3、第一个信号是20K，第二个信号是60K
    // 4、第一个信号是25K，第二个信号是75K
    // 5、第一个信号是30K，第二个信号是90K
    conti = ((frq[0] == 0) & (frq[1] == 4)) | 
            ((frq[0] == 1) & (frq[1] == 7)) | 
            ((frq[0] == 2) & (frq[1] == 10)) | 
            ((frq[0] == 3) & (frq[1] == 13)) | 
            ((frq[0] == 4) & (frq[1] == 16));
    if (conti)
    {
        // 计算五次谐波能量和1次谐波能量之比
        temp_float = (float)frq[0] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
        temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
        temp_float = temp_float * 512;       // 计算输入信号频率对应的数组索引
        index = temp_float + 0.5f;            // 进行四舍五入取整
        mag_1harmo[0] = mag[index - 1] + mag[index] + mag[index + 1];

        temp_float = (float)frq[0] * 5 + 10; // 计算输入索引值所对应的真实频率，单位为KHz
        temp_float = temp_float / 500;       // 采样率为1MSPS，则输入频率是奈奎斯特频率的多少倍
        temp_float = temp_float * 5 * 512;   // 计算5倍基频对应的数组索引
        harmo5_index = temp_float + 0.5f;     // 进行四舍五入取整
        mag_5harmo = mag[harmo5_index - 1] + mag[harmo5_index] + mag[harmo5_index + 1];
        k[0] = mag_1harmo[0] / mag_5harmo;
        if (k[0] > 70)
            wave_type[0] = 0; // 5次谐波较小，说明是正弦波
        else
            wave_type[0] = 1; // 5次谐波较大，说明是三角波
    }
}
